  {academicSubtab==='My Courses'&&<div className="grid gap-4 md:grid-cols-2">{accepted.map(e=><article key={e.id} className="rounded-2xl border bg-white p-5"><p className="text-xs font-bold uppercase text-cyan-800">{e.admission_number||'Admission number pending'}</p><h4 className="mt-2 text-lg font-black">{e.course_title}</h4><p className="mt-1 text-sm text-slate-500">Intake: {e.preferred_intake||'Not assigned'} · Status: {e.status}</p><button onClick={()=>setAcademicSubtab('Learning')} className="mt-4 rounded-xl bg-cyan-900 px-4 py-2 text-sm font-bold text-white">Open course</button></article>)}{!accepted.length&&<Empty title="No approved courses yet" detail="Your courses will appear after Admissions approves your application."/>}</div>}
